import { describe, it, expect } from 'vitest';
import { generatedUmlConstraints } from './GeneratedUmlConstraints';

describe('Auto-Generated UML Constraints', () => {
  it('should have parsed constraints from the legacy Lisp file', () => {
    // We expect a robust number of constraints to have been generated by lisp2ts.js
    expect(generatedUmlConstraints.length).toBeGreaterThan(100);
    
    // Verify structure of first rule
    const firstRule = generatedUmlConstraints[0];
    expect(firstRule).toHaveProperty('targetType');
    expect(firstRule).toHaveProperty('ruleName');
    expect(firstRule).toHaveProperty('evaluate');
  });
});
